def split_csv_line(line: str) -> list[str]:
    result = []
    current_field = []
    i = 0
    in_quotes = False

    while i < len(line):
        char = line[i]

        if char == '"':
            if in_quotes:
                # Inside quotes: check for doubled-quote escape
                if i + 1 < len(line) and line[i + 1] == '"':
                    current_field.append('"')
                    i += 1  # Skip the second quote
                else:
                    in_quotes = False
            else:
                # Outside quotes: start a quoted field
                in_quotes = True
        elif char == ',' and not in_quotes:
            result.append(''.join(current_field))
            current_field = []
        else:
            current_field.append(char)

        i += 1

    result.append(''.join(current_field))

    return result
```

```python
def parse_headers(raw: str) -> dict[str, str]:
    lines = raw.splitlines()
    result: dict[str, str] = {}

    for line in lines:
        if not line.strip():
            continue

        if ':' not in line:
            raise ValueError("Line does not contain ':'.")

        colon_idx = line.index(':')
        name = line[:colon_idx].lower()
        value = line[colon_idx+1:].strip()

        if name in result:
            result[name] += ', ' + value
        else:
            result[name] = value

    return result
