import re
from decimal import Decimal

def parse_brl(s: str) -> Decimal:
    s = s.strip()
    if not s:
        raise ValueError("Empty string")

    negative = False

    # Handle outer parentheses for negative
    if s.startswith('(') and s.endswith(')'):
        inner = s[1:-1]
        if inner.strip().startswith('-'):
            raise ValueError("Conflicting negative markers")
        if not inner.strip():
            raise ValueError("No number inside parentheses")
        negative = True
        s = inner.strip()

    # Handle leading minus sign
    if s.startswith('-') and not s.startswith('('):
        negative = True
        s = s[1:]

    # Remove R$ prefix
    if s.startswith('R$'):
        s = s[2:]

    s = s.strip()
    if not s:
        raise ValueError("No number found")

    # Validate only allowed characters in the remaining string
    if not re.match(r'^[\d.,]+$', s):
        raise ValueError(f"Invalid characters: {s}")

    # Split by comma to separate integer and cents
    parts = s.split(',')
    if len(parts) > 2:
        raise ValueError("Too many commas")

    int_part = parts[0]
    cents_part = parts[1] if len(parts) == 2 else ''

    # Validate cents: must be exactly 2 digits or absent
    if cents_part:
        if not cents_part.isdigit() or len(cents_part) != 2:
            raise ValueError(f"Cents must be exactly 2 digits, got '{cents_part}'")

    # Validate integer part contains only digits and dots
    int_digits = int_part.replace('.', '')
    if not int_digits.isdigit():
        raise ValueError(f"Invalid integer part: '{int_part}'")

    # Validate dot placement for thousand separators
    if '.' in int_part:
        if int_part.startswith('.') or int_part.endswith('.'):
            raise ValueError("Dot cannot be at start or end of integer part")

        expected_dots = sorted(
            [len(int_digits) - 3 * k for k in range(1, (len(int_digits) // 3) + 1)]
        )

        actual_dots = sorted(int_part.index('.') for dot in re.findall(r'(?<![^.] \.)\.', int_part) if dot is not None)
        # Simpler: collect actual dot positions
        actual_dots = [i for i, ch in enumerate(int_part) if ch == '.']

        if actual_dots != expected_dots:
            raise ValueError(f"Invalid thousand separator grouping: '{int_part}'")

    value_str = str(int(digits_only := int_digits)) + '.' + cents_part if cents_part else str(int(digits_only))
    return Decimal(value_str) if cents_part else Decimal(str(int(digits_only)))
```

