def compare_versions(a: str, b: str) -> int:
    def parse_version(version: str):
        # Strip build metadata (everything after '+' is ignored)
        if '+' in version:
            version = version.split('+')[0]

        # Split base version and pre-release
        if '-' in version:
            base, prerelease = version.rsplit('-', 1)
        else:
            base, prerelease = version, ''

        # Parse major.minor.patch
        parts = base.split('.')
        maj = int(parts[0]) if len(parts) >= 1 else 0
        min_ = int(parts[1]) if len(parts) >= 2 else 0
        pat = int(parts[2]) if len(parts) >= 3 else 0

        # Parse prerelease identifiers
        pre_ids = []
        if prerelease:
            for id in prerelease.split('.'):
                try:
                    pre_ids.append((True, int(id)))
                except ValueError:
                    pre_ids.append((False, id))

        return (maj, min_, pat, pre_ids)

    a_parsed = parse_version(a)
    b_parsed = parse_version(b)

    maj_a, min_a, pat_a, pre_a = a_parsed
    maj_b, min_b, pat_b, pre_b = b_parsed

    # Compare major.minor.patch
    for val_a, val_b in [(maj_a, maj_b), (min_a, min_b), (pat_a, pat_b)]:
        if val_a != val_b:
            return -1 if val_a < val_b else 1

    # Compare prerelease identifiers dot by dot
    max_len = max(len(pre_a), len(pre_b))
    for i in range(max_len):
        if i >= len(pre_a):
            t1, v1 = False, None
        else:
            t1, v1 = pre_a[i]

        if i >= len(pre_b):
            t2, v2 = False, None
        else:
            t2, v2 = pre_b[i]

        # Shorter list is lower (exhausted identifier)
        if v1 is None and v2 is not None:
            return -1
        if v2 is None and v1 is not None:
            return 1

        # Both numeric: compare as numbers
        if t1 == True and t2 == True:
            if v1 != v2:
                return -1 if v1 < v2 else 1

        # One numeric, one alphanumeric: numeric is lower
        if t1 == True and t2 == False:
            return -1
        if t1 == False and t2 == True:
            return 1

        # Both alphanumeric: lexicographic comparison
        s1, s2 = v1, v2
        if s1 < s2:
            return -1
        elif s1 > s2:
            return 1

    return 0
