import re

def natural_sorted(names: list[str]) -> list[str]:
    def sort_key(s: str):
        parts = re.findall(r'([a-zA-Z]+|\d+)', s)
        return [(0, int(part)) if part.isdigit() else (1, part.lower()) for part in parts]

    return sorted(names, key=sort_key)
