import unicodedata

def sort_names(names: list[str]) -> list[str]:
    def sort_key(name):
        # Primary: lowercase + decomposed, stripped of accents for case-insensitive, accent-insensitive ordering
        n = unicodedata.normalize('NFKD', name.lower())
        no_accents = ''.join(c for c in n if not unicodedata.combining(c))

        # Secondary: number of accented characters (combining marks) in the decomposed form
        accent_count = sum(1 for c in n if unicodedata.combining(c) > 0)

        # Tertiary: original string for final lexicographic tie-breaking
        return (no_accents, accent_count, name)

    return sorted(names, key=sort_key)
```

