def deep_merge(base: dict, override: dict) -> dict:
    def _deep_copy(value):
        if isinstance(value, dict):
            return {k: _deep_copy(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_deep_copy(item) for item in value]
        else:
            return value

    result = {}

    for key in set(base.keys()) | set(override.keys()):
        base_val = base.get(key)
        override_val = override.get(key)

        if key in override and override_val is None:
            continue

        if isinstance(base_val, dict) and isinstance(override_val, dict):
            result[key] = deep_merge(base_val, override_val)
        elif key not in override:
            result[key] = _deep_copy(base_val)
        else:
            result[key] = _deep_copy(override_val)

    return result
