```python
from datetime import datetime, timezone

def latest_by_key(records: list[dict], key: str) -> list[dict]:
    best = {}  # key_value -> (record, index, updated_at_parsed)
    first_appearance = {}  # key_value -> index in records

    for i, rec in enumerate(records):
        k_val = rec.get(key)
        if k_val not in first_appearance:
            first_appearance[k_val] = i

        try:
            ts_str = rec.get('updated_at', '')
            # Replace 'Z' with '+00:00' for fromisoformat compatibility
            ts = datetime.fromisoformat(ts_str.replace('Z', '+00:00'))
        except (ValueError, TypeError):
            ts = datetime.min.replace(tzinfo=timezone.utc)

        if k_val not in best:
            best[k_val] = (rec, i, ts)
        else:
            curr_rec, curr_idx, curr_ts = best[k_val]
            # Keep the record with the latest actual instant; tie-break to later index
            if ts >= curr_ts:
                best[k_val] = (rec, i, ts)

    # Return in the order of first appearance of each key value
    sorted_keys = sorted(first_appearance.keys(), key=lambda k: first_appearance[k])
    return [best[k][0] for k in sorted_keys]
