import re

def parse_duration(s: str) -> int:
    if not s or not s.strip():
        raise ValueError("Empty or invalid string")

    pattern = r'^(\d+[hms]+)+$'
    if not re.match(pattern, s):
        raise ValueError("Invalid format")

    seconds = 0
    for num_str, unit in re.findall(r'(\d+)([hms])', s):
        multiplier = {'h': 3600, 'm': 60, 's': 1}[unit]
        seconds += int(num_str) * multiplier

    return int(seconds)
