def split_csv_line(line: str) -> list[str]:
    fields = []
    current_field = []
    in_quotes = False
    i = 0

    while i < len(line):
        ch = line[i]

        if ch == '"':
            if in_quotes:
                if i + 1 < len(line) and line[i+1] == '"':
                    current_field.append('"')
                    i += 2
                    continue
                else:
                    in_quotes = False
                    i += 1
                    continue
            else:
                in_quotes = True
                i += 1
                continue

        if not in_quotes:
            if ch == ',':
                fields.append(''.join(current_field))
                current_field = []
            else:
                current_field.append(ch)
        else:
            current_field.append(ch)

        i += 1

    fields.append(''.join(current_field))

    return fields
