import math

def compact(n: int) -> str:
    if n < 1000:
        return str(n)

    def round_half_up(x):
        return math.floor(x * 10 + 0.5) / 10

    for div, unit in [(10**9, 'bi'), (10**6, 'mi'), (1000, 'mil')]:
        val = round_half_up(n / div)
        if val >= 1.0:
            s = f"{val:.1f}"
            if s.endswith(',0'):
                s = s[:-2]
            return s + ' ' + unit

    return str(n)
