import re
from decimal import Decimal

def parse_brl(s: str) -> Decimal:
    s = s.strip()

    # Track negativity based on original string
    negative = False

    # Check for leading minus (not inside parentheses yet)
    if s.startswith('-'):
        negative = True
        s = s[1:]

    # Check for surrounding parentheses
    if s.startswith('(') and s.endswith(')'):
        negative = True
        if len(s) < 2:
            raise ValueError("Invalid format")
        s = s[1:-1]

    # Remove R$ prefix
    if s.startswith('R$'):
        s = s[2:]

    s = s.strip()

    if not s:
        raise ValueError("Empty string")

    # Split by comma to separate integer and cents
    parts = s.split(',')
    int_part = parts[0]

    # Cents must be exactly 2 digits if present
    if len(parts) > 1:
        cents_str = parts[1]
        if len(cents_str) != 2 or not cents_str.isdigit():
            raise ValueError("Cents must be exactly 2 digits")
    else:
        cents_str = ''

    # Validate integer part format
    has_dot = '.' in int_part

    if has_dot:
        groups = int_part.split('.')
        for i, g in enumerate(groups):
            if not g:
                raise ValueError("Invalid integer part format")
            if i > 0 and len(g) != 3:
                raise ValueError("Integer groups must be exactly 3 digits")
    else:
        # No dot - must be all digits
        if not int_part.isdigit():
            raise ValueError(f"Invalid integer part: '{int_part}'")

    # Ensure no other invalid characters remain in integer part
    if has_dot:
        cleaned = re.sub(r'[.]', '', int_part)
        if not cleaned.isdigit():
            raise ValueError("Invalid characters in integer part")
    else:
        cleaned = int_part
        if not cleaned.isdigit():
            raise ValueError("Invalid characters in integer part")

    # Build final decimal string
    cents_digits = 0 if not cents_str else int(cents_str)
    result_parts = f"{cleaned}.{cents_digits:02d}"

    return (-Decimal(result_parts)) if negative else Decimal(result_parts)
