from datetime import date, timedelta
from typing import Set


def add_business_days(d: date, n: int, holidays: Set[date]) -> date:
    if n == 0:
        if 0 <= d.weekday() <= 4 and d not in holidays:
            return d
        candidate = d + timedelta(days=1)
        while True:
            if 0 <= candidate.weekday() <= 4 and candidate not in holidays:
                return candidate
            candidate += timedelta(days=1)

    direction = 1 if n > 0 else -1
    steps = abs(n)
    candidate = d + timedelta(days=direction)
    count = 0

    while count < steps:
        if 0 <= candidate.weekday() <= 4 and candidate not in holidays:
            count += 1
            if count == steps:
                return candidate
        candidate += timedelta(days=direction)
