def compare_versions(a: str, b: str) -> int:
    def parse(v):
        # Split build metadata (after +) - ignored for comparison
        if '+' in v:
            v_main = v.rsplit('+', 1)[0]
        else:
            v_main = v

        # Split pre-release (before -)
        if '-' in v_main:
            v_core, v_prerelease = v_main.rsplit('-', 1)
        else:
            v_core, v_prerelease = v_main, ''

        # Parse core version numbers (MAJOR.MINOR.PATCH)
        core = [int(x) for x in v_core.split('.')]

        # Parse pre-release identifiers
        prerelease_ids = []
        if v_prerelease:
            for id in v_prerelease.split('.'):
                if id and id.isdigit():
                    prerelease_ids.append(('num', int(id)))
                else:
                    prerelease_ids.append(('alphanum', id))

        return (core, prerelease_ids)

    a_parsed = parse(a)
    b_parsed = parse(b)

    core_a, pre_a = a_parsed
    core_b, pre_b = b_parsed

    # Compare core parts (MAJOR.MINOR.PATCH)
    for i in range(3):
        ca = core_a[i] if i < len(core_a) else 0
        cb = core_b[i] if i < len(core_b) else 0
        if ca != cb:
            return -1 if ca < cb else 1

    # Compare pre-release
    has_prerelease_a = len(pre_a) > 0
    has_prerelease_b = len(pre_b) > 0

    if not has_prerelease_a and not has_prerelease_b:
        return 0

    if has_prerelease_a and not has_prerelease_b:
        return -1  # pre-release < release

    if not has_prerelease_a and has_prerelease_b:
        return 1  # release > pre-release

    # Both have pre-release, compare identifiers dot by dot
    for i in range(min(len(pre_a), len(pre_b))):
        id_a_type, id_a_val = pre_a[i]
        id_b_type, id_b_val = pre_b[i]

        if id_a_type == 'num' and id_b_type == 'alphanum':
            return -1  # numeric < alphanumeric
        elif id_a_type == 'alphanum' and id_b_type == 'num':
            return 1   # alphanumeric > numeric

        # Same type, compare values
        val_a = id_a_val if id_a_type == 'num' else id_a_val
        val_b = id_b_val if id_b_type == 'num' else id_b_val

        if val_a < val_b:
            return -1
        elif val_a > val_b:
            return 1

    # All identifiers compared equally, shorter list is lower
    if len(pre_a) < len(pre_b):
        return -1
    elif len(pre_a) > len(pre_b):
        return 1

    return 0
