import heapq
from collections import defaultdict

def build_order(deps: dict[str, list[str]]) -> list[str]:
    all_items = set()
    for dep_list in deps.values():
        all_items.update(dep_list)
    all_items.update(deps.keys())

    in_degree = {item: 0 for item in all_items}
    graph = defaultdict(list)

    for item, dependent_list in deps.items():
        for dep in dependent_list:
            in_degree[item] += 1
            graph[dep].append(item)

    heap = [item for item in all_items if in_degree[item] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        current = heapq.heappop(heap)
        result.append(current)

        for dependent in graph[current]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) != len(all_items):
        raise ValueError("Cycle detected")

    return result
