def wrap(text: str, width: int) -> list[str]:
    words = text.split()

    if not words:
        return []

    tokens = []
    for word in words:
        for i in range(0, len(word), width):
            tokens.append(word[i:i + width])

    lines = []
    current_line = ""

    for token in tokens:
        if not current_line:
            current_line = token
        else:
            if len(current_line) + 1 + len(token) <= width:
                current_line += " " + token
            else:
                lines.append(current_line)
                current_line = token

