def set_ini_value(text: str, section: str, key: str, value: str) -> str:
    lines = text.splitlines(keepends=True)
    target_index = None

    for i, line in enumerate(lines):
        stripped = line.strip()

        if stripped.startswith('[') and stripped.endswith(']'):
            actual_section = stripped[1:-1]
            if actual_section == section:
                for j in range(i + 1, len(lines)):
                    other_line = lines[j]
                    other_stripped = other_line.strip()

                    if not other_stripped or other_stripped.startswith(';') or other_stripped.startswith('#'):
                        continue

                    if '=' in other_stripped:
                        parts = other_stripped.split('=', 1)
                        if len(parts) == 2 and parts[0].strip() == key:
                            target_index = j
                            break

        if target_index is not None:
            break

    if target_index is None:
        raise KeyError(f"Section '{section}' or key '{key}' does not exist")

    result = []
    for i, line in enumerate(lines):
        if i == target_index:
            result.append(f"{key} = {value}")
        else:
            result.append(line)

    return ''.join(result)
