def deep_merge(base: dict, override: dict) -> dict:
    def _deepcopy(val):
        if isinstance(val, dict):
            return {k: _deepcopy(v) for k, v in val.items()}
        elif isinstance(val, list):
            return [_deepcopy(item) for item in val]
        else:
            return val

    result = {}

    all_keys = set(base.keys()) | set(override.keys())

    for key in all_keys:
        base_val = base.get(key)
        override_val = override.get(key)

        if key in override and override_val is None:
            continue

        if override_val is not None:
            if isinstance(base_val, dict) and isinstance(override_val, dict):
                result[key] = deep_merge(base_val, override_val)
            else:
                result[key] = _deepcopy(override_val)
        else:
            result[key] = _deepcopy(base_val)

    return result
