def is_woodall(n):
    """
    Check if the given number is prime (is_woodall).
    A number is considered woodball/woodall if it is a prime number.
    """
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True
