import re

def parse_duration(s: str) -> int:
    if not s or not s.strip():
        raise ValueError("Invalid or empty string")

    cleaned = s.strip()

    # Validate that only digits and units (h, m, s) are present
    if not re.match(r'^[0-9hms]+$', cleaned):
        raise ValueError("Invalid duration string")

    matches = re.findall(r'(\d+)([hms])', cleaned)
    total_seconds = 0

    for digits, unit in matches:
        multiplier = {'h': 3600, 'm': 60, 's': 1}
        total_seconds += int(digits) * multiplier[unit]

    # Verify all characters in the string were matched by the pattern
    if sum(len(d) + len(u) for d, u in matches) != len(cleaned):
        raise ValueError("Invalid duration string")

    return total_seconds
