import re
from decimal import Decimal

def parse_brl(s: str) -> Decimal:
    s = s.strip()
    if not s:
        raise ValueError("Empty string")

    is_negative = False

    # Check for negative indicator at the beginning
    if s.startswith('-'):
        is_negative = True
        s = s[1:]
    elif s.startswith('('):
        is_negative = True
        if not s.endswith(')'):
            raise ValueError("Mismatched parentheses")
        s = s[1:-1]

    # Remove R$ prefix (with optional surrounding whitespace)
    idx = s.find('R$')
    if idx != -1:
        # Check that R$ is a prefix (accounting for possible '-' before it)
        if idx < 2:
            raise ValueError("R$ not found or invalid position")
        s = s[idx + 2:]

    s = s.strip()

    if not s:
        raise ValueError("No numeric content")

    # Split by comma to separate integer and cents parts
    parts = s.split(',')
    if len(parts) == 1:
        int_part_str = parts[0]
        cents_str = ''
    else:
        int_part_str = parts[0]
        cents_str = parts[1]

    # Validate integer part is not empty
    if not int_part_str:
        raise ValueError("Empty integer part")

    # All characters in integer part must be digits or dots
    if not all(c.isdigit() or c == '.' for c in int_part_str):
        raise ValueError("Integer part contains non-digit, non-dot characters")

    # Validate dot grouping: groups of exactly 3 from the right
    if '.' in int_part_str:
        groups = int_part_str.split('.')
        for i, g in enumerate(groups):
            if not g or not g.isdigit():
                raise ValueError(f"Invalid integer part format: {int_part_str}")
            # All groups except the first should be exactly 3 digits
            if i > 0 and len(g) != 3:
                raise ValueError("Integer part groups must be exactly 3 digits")

    # Build clean integer string (remove dots)
    int_part = int_part_str.replace('.', '')
    if not int_part:
        raise ValueError("Empty integer part after dot removal")

    if not int_part.isdigit():
        raise ValueError("Non-digit characters in integer part")

    # Validate cents
    if cents_str:
        if len(cents_str) != 2:
            raise ValueError("Cents must be exactly 2 digits")
        if not cents_str.isdigit():
            raise ValueError("Cents contain non-digit characters")
        cents_val = int(cents_str)
    else:
        cents_val = 0

    # Construct Decimal value
    if cents_val == 0:
        value = Decimal(int_part)
    else:
        value = Decimal(f"{int_part}.{cents_val:02d}")

    if is_negative:
        value = -value

    return value
