from datetime import date, timedelta


def add_business_days(d: date, n: int, holidays: set[date]) -> date:
    def is_business_day(day: date) -> bool:
        if day.weekday() >= 5:
            return False
        return day not in holidays

    # Special case for n == 0
    if n == 0:
        if is_business_day(d):
            return d
        else:
            candidate = d + timedelta(days=1)
            while not is_business_day(candidate):
                candidate += timedelta(days=1)
            return candidate

    # For n != 0, move in the appropriate direction from d (d itself doesn't count)
    direction = 1 if n > 0 else -1
    candidate = d + timedelta(days=direction)

    for _ in range(abs(n)):
        while not is_business_day(candidate):
            candidate += timedelta(days=direction)
        # Advance past this business day to check the next one for the remaining count
        candidate += timedelta(days=direction)

    # Step back one step to return the actual nth business day
    return candidate - timedelta(days=direction)
