def compare_versions(a: str, b: str) -> int:
    def parse_version(v: str):
        if '+' in v:
            base = v.split('+', 1)[0]
        else:
            base = v

        if '-' in base:
            base_parts, prerelease = base.split('-', 1)
        else:
            base_parts = base
            prerelease = None

        major, minor, patch = map(int, base_parts.split('.'))
        return major, minor, patch, prerelease

    def is_numeric(x: str) -> bool:
        return x.isdigit()

    def compare_prerelease(ids_a, ids_b):
        max_len = max(len(ids_a), len(ids_b))
        for i in range(max_len):
            id_a = ids_a[i] if i < len(ids_a) else ''
            id_b = ids_b[i] if i < len(ids_b) else ''

            a_is_num = is_numeric(id_a)
            b_is_num = is_numeric(id_b)

            if not a_is_num and not b_is_num:
                if id_a < id_b:
                    return -1
                elif id_a > id_b:
                    return 1
            elif a_is_num and b_is_num:
                na, nb = int(id_a), int(id_b)
                if na < nb:
                    return -1
                elif na > nb:
                    return 1
            elif a_is_num:
                return -1
            elif b_is_num:
                return 1

        if len(ids_a) < len(ids_b):
            return -1
        elif len(ids_a) > len(ids_b):
            return 1
        return 0

    pa = parse_version(a)
    pb = parse_version(b)

    for i in range(3):
        if pa[i] < pb[i]:
            return -1
        elif pa[i] > pb[i]:
            return 1

    return compare_prerelease(pa[3], pb[3])
