    n = len(lines)

    # Find the first [section] header matching our target section
    target_section_index = None
    for i in range(n):
        s = lines[i].strip()
        if s.startswith('[') and s.endswith(']'):
            sec_name = s[1:-1]
            if sec_name == section:
                target_section_index = i
                break

    if target_section_index is None:
        raise KeyError(f"Section '{section}' not found")

    # Find the key line within that section and mark it for replacement
    in_target_section = False
    key_line_index = None

    for i in range(n):
        s = lines[i].strip()

        # Check if this is a section header
        if s.startswith('[') and s.endswith(']'):
            sec_name = s[1:-1]
            if sec_name == section:
                in_target_section = True
            else:
                in_target_section = False

        # Look for the key within the target section, ignoring spaces around '='
        if in_target_section and key_line_index is None and '=' in lines[i]:
            left, _, right = lines[i].partition('=')
            if left.strip() == key:
                key_line_index = i

    if key_line_index is None:
        raise KeyError(f"Key '{key}' not found in section '{section}'")

    # Replace only that line with key = value
    result_lines = list(lines)
    result_lines[key_line_index] = f"{key} = {value}"

