def deep_merge(base: dict, override: dict) -> dict:
    import copy

    def _merge(b: dict, o: dict) -> dict:
        result = {}

        # Collect all keys from both dictionaries
        all_keys = set(b.keys()) | set(o.keys())

        for key in all_keys:
            b_val = b.get(key)
            o_val = o.get(key)

            if key in o and o_val is not None:
                # Key exists in override with a non-None value
                if isinstance(b_val, dict) and isinstance(o_val, dict):
                    # Both are dicts: merge recursively
                    result[key] = _merge(copy.deepcopy(b_val), o_val)
                else:
                    # Override wins: copy the override value
                    result[key] = copy.deepcopy(o_val)
            elif key in b:
                # Key only exists in base: keep it (deep copied)
                result[key] = copy.deepcopy(b_val)

        return result

    return _merge(copy.deepcopy(base), override)
