import ipaddress

def ip_allowed(ip: str, networks: list[str]) -> bool:
    try:
        addr = ipaddress.ip_address(ip)
    except ValueError:
        return False

    ipv4_mapped = None
    if isinstance(addr, ipaddress.IPv6Address):
        ipv4_mapped = addr.ipv4_mapped

    for net_str in networks:
        try:
            if '/' not in net_str:
                raise ValueError("Network must contain CIDR notation")

            network = ipaddress.IPv4Network(net_str) if ':' not in net_str else ipaddress.IPv6Network(net_str)
        except (ValueError, ipaddress.AddressValueError):
            raise ValueError(f"Invalid network '{net_str}'")

        try:
            if addr in network:
                return True
        except ValueError:
            continue

    if ipv4_mapped is not None:
        for net_str in networks:
            try:
                network = ipaddress.IPv4Network(net_str)
                if ipv4_mapped in network:
                    return True
            except (ValueError, ipaddress.AddressValueError):
                raise ValueError(f"Invalid network '{net_str}'")

    return False
