def remove_Occ(s, char):
    indices = [i for i, c in enumerate(s) if c == char]
    if not indices:
        return s

    first = indices[0]
    last = indices[-1]

    result = []
    for i in range(len(s)):
        if i == first or i == last:
            continue
        result.append(s[i])
    return ''.join(result)
